INSERT INTO tickets (ticket_id, ticket_no, company_id, contact_id, assigned_to, topic, priority, status, title, description, due_at, created_at, updated_at) VALUES
 (1, 'TKT-0001', 1, 1, 3, 'bug', 'critical', 'in_progress', 'Invoice total does not match', 'Totals on printed invoices differ from the screen by a few rupees.', DATE_ADD(NOW(), INTERVAL -2 DAY), DATE_SUB(NOW(), INTERVAL 20 DAY), DATE_SUB(NOW(), INTERVAL 19 DAY)),
 (2, 'TKT-0002', 2, 2, 5, 'query', 'medium', 'waiting', 'Add a new tax rate', 'How do we add a 12% rate for the new item group?', DATE_ADD(NOW(), INTERVAL 3 DAY), DATE_SUB(NOW(), INTERVAL 19 DAY), DATE_SUB(NOW(), INTERVAL 18 DAY)),
 (3, 'TKT-0003', 3, 3, 14, 'bug', 'high', 'open', 'Stock screen freezes', 'The stock list hangs for about a minute when more than 500 items load.', DATE_ADD(NOW(), INTERVAL 4 DAY), DATE_SUB(NOW(), INTERVAL 18 DAY), DATE_SUB(NOW(), INTERVAL 17 DAY)),
 (4, 'TKT-0004', 4, 4, 8, 'customization', 'critical', 'in_progress', 'Custom delivery challan format', 'We need our logo and a vehicle number box on the challan.', DATE_ADD(NOW(), INTERVAL 5 DAY), DATE_SUB(NOW(), INTERVAL 17 DAY), DATE_SUB(NOW(), INTERVAL 16 DAY)),
 (5, 'TKT-0005', 5, 5, 9, 'bug', 'critical', 'open', 'Cannot log in after password reset', 'The reset link works but the new password is rejected.', DATE_ADD(NOW(), INTERVAL -2 DAY), DATE_SUB(NOW(), INTERVAL 16 DAY), DATE_SUB(NOW(), INTERVAL 15 DAY)),
 (6, 'TKT-0006', 6, 6, 17, 'query', 'medium', 'in_progress', 'Export ledger to Excel', 'Is there a way to export the party ledger with opening balances?', NULL, DATE_SUB(NOW(), INTERVAL 15 DAY), DATE_SUB(NOW(), INTERVAL 14 DAY)),
 (7, 'TKT-0007', 7, 7, 12, 'bug', 'high', 'resolved', 'Barcode labels print blank', 'Labels come out empty on the new thermal printer.', DATE_ADD(NOW(), INTERVAL -3 DAY), DATE_SUB(NOW(), INTERVAL 14 DAY), DATE_SUB(NOW(), INTERVAL 13 DAY)),
 (8, 'TKT-0008', 8, 8, 14, 'query', 'critical', 'open', 'Month end closing steps', 'Please share the closing checklist for the accounts module.', DATE_ADD(NOW(), INTERVAL 9 DAY), DATE_SUB(NOW(), INTERVAL 13 DAY), DATE_SUB(NOW(), INTERVAL 12 DAY)),
 (9, 'TKT-0009', 9, 9, 3, 'customization', 'low', 'in_progress', 'Add a field for vehicle number', 'A vehicle number field on the dispatch screen, searchable.', DATE_ADD(NOW(), INTERVAL -2 DAY), DATE_SUB(NOW(), INTERVAL 12 DAY), DATE_SUB(NOW(), INTERVAL 11 DAY)),
 (10, 'TKT-0010', 10, 10, 16, 'bug', 'medium', 'open', 'Wrong GST on credit note', 'Credit notes pick the old GST rate for returned items.', DATE_ADD(NOW(), INTERVAL 2 DAY), DATE_SUB(NOW(), INTERVAL 11 DAY), DATE_SUB(NOW(), INTERVAL 10 DAY)),
 (11, 'TKT-0011', 11, 11, 17, 'query', 'high', 'in_progress', 'Bulk import of customers', 'Can we import 2,000 customers from a spreadsheet?', DATE_ADD(NOW(), INTERVAL 3 DAY), DATE_SUB(NOW(), INTERVAL 10 DAY), DATE_SUB(NOW(), INTERVAL 9 DAY)),
 (12, 'TKT-0012', 12, 12, 8, 'bug', 'critical', 'waiting', 'Dashboard shows old figures', 'Sales totals on the dashboard look a day behind.', NULL, DATE_SUB(NOW(), INTERVAL 9 DAY), DATE_SUB(NOW(), INTERVAL 8 DAY)),
 (13, 'TKT-0013', 13, 13, 2, 'customization', 'low', 'open', 'Role based screens for store staff', 'Store staff should see only the stock and dispatch screens.', DATE_ADD(NOW(), INTERVAL -2 DAY), DATE_SUB(NOW(), INTERVAL 8 DAY), DATE_SUB(NOW(), INTERVAL 7 DAY)),
 (14, 'TKT-0014', 14, 14, 3, 'query', 'medium', 'resolved', 'Printing two copies of a bill', 'How do we print the original and duplicate on one go?', DATE_ADD(NOW(), INTERVAL -3 DAY), DATE_SUB(NOW(), INTERVAL 7 DAY), DATE_SUB(NOW(), INTERVAL 6 DAY)),
 (15, 'TKT-0015', 15, 15, 5, 'bug', 'high', 'open', 'Slow report for last year', 'The yearly sales report takes over five minutes.', DATE_ADD(NOW(), INTERVAL 7 DAY), DATE_SUB(NOW(), INTERVAL 6 DAY), DATE_SUB(NOW(), INTERVAL 5 DAY)),
 (16, 'TKT-0016', 16, 16, 6, 'query', 'critical', 'in_progress', 'Link e-invoice to the portal', 'Steps to connect the e-invoice portal credentials.', DATE_ADD(NOW(), INTERVAL 8 DAY), DATE_SUB(NOW(), INTERVAL 5 DAY), DATE_SUB(NOW(), INTERVAL 4 DAY)),
 (17, 'TKT-0017', 17, 17, NULL, 'bug', 'low', 'open', 'Mobile app crash on login', 'The field staff app closes right after the login screen.', DATE_ADD(NOW(), INTERVAL -2 DAY), DATE_SUB(NOW(), INTERVAL 4 DAY), DATE_SUB(NOW(), INTERVAL 3 DAY)),
 (18, 'TKT-0018', 18, 18, NULL, 'customization', 'medium', 'open', 'Custom salary slip layout', 'Add basic, allowances and deductions in separate columns.', NULL, DATE_SUB(NOW(), INTERVAL 3 DAY), DATE_SUB(NOW(), INTERVAL 2 DAY)),
 (19, 'TKT-0019', 19, 19, NULL, 'query', 'high', 'open', 'Reminder emails for dues', 'Can the system email a reminder when a payment is overdue?', DATE_ADD(NOW(), INTERVAL 2 DAY), DATE_SUB(NOW(), INTERVAL 2 DAY), DATE_SUB(NOW(), INTERVAL 1 DAY)),
 (20, 'TKT-0020', 20, 20, NULL, 'bug', 'critical', 'open', 'Duplicate entries in purchase list', 'The same purchase order appears twice after editing.', DATE_ADD(NOW(), INTERVAL 3 DAY), DATE_SUB(NOW(), INTERVAL 1 DAY), DATE_SUB(NOW(), INTERVAL 0 DAY));
